DeviceProperties.ListenerScriptPacketParser:
IF RECEIVEDMSG.TOPIC =  "nuki/" + deviceid + "/state"
  VAR state := TODOUBLE(TOSTRING(RECEIVEDMSG.PAYLOAD));
  IF state <= 7
    Mu := state;
  ELSEIF state = 254
    Mu := 8;
  ELSE
    Mu := 9;
  END 
END

